/* Separate public-equity research workspace. Widgets own market data and timestamps. */
(()=>{
const crypto=document.querySelector('main');if(!crypto)return;
const nav=document.createElement('nav');nav.className='asset-nav';nav.id='workspaceNavigation';nav.tabIndex=-1;nav.setAttribute('aria-label','Asset workspace');nav.innerHTML='<strong>MARKET RADAR</strong><button data-asset="crypto" aria-pressed="true">Crypto</button><button data-asset="stocks" aria-pressed="false">Global stocks</button><button data-asset="indices" aria-pressed="false">Global indices</button>';crypto.before(nav);
const stocks=document.createElement('main');stocks.id='stocksWorkspace';stocks.hidden=true;crypto.after(stocks);
const style=document.createElement('style');style.textContent=`.asset-nav{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:18px 24px;border-bottom:1px solid #d7e3df;background:#f4f8f6;color:#183e35}.asset-nav strong{margin-right:auto;letter-spacing:2px;font-size:13px}.asset-nav button,.stock-tabs button,#stocksWorkspace button{padding:10px 16px;border:1px solid #bdcec7;border-radius:8px;background:#fff;color:#244e43;cursor:pointer}.asset-nav [aria-pressed=true],.stock-tabs [aria-current=page]{background:#245b4b;color:white}#stocksWorkspace{font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;font-size:15px;max-width:1500px;margin:auto;padding:26px;color:#203e35}#stocksWorkspace[hidden],main[hidden]{display:none!important}.stock-intro{display:flex;justify-content:space-between;gap:20px;align-items:center}.stock-intro h1{font-size:30px;margin:10px 0}.stock-note{padding:14px 18px;background:#eef5f1;border:1px solid #cfdfd6;border-radius:10px;line-height:1.6;margin:16px 0;color:#426055}.stock-tabs{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}.stock-controls{display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin:18px 0}.stock-controls label{display:grid;gap:7px}.stock-controls select,.stock-controls input{background:white;color:#203e35;padding:11px;border:1px solid #bdcec7;border-radius:8px;max-width:100%}.stock-card{border:1px solid #d7e3df;border-radius:12px;background:#fff;padding:18px;margin:18px 0;overflow:hidden}.stock-card h2{font-size:20px;margin:0 0 8px}.stock-card a{color:#24644f;text-decoration:underline}.stock-widget{height:600px;width:100%}.stock-widget.chart{height:650px}.stock-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.stock-company{border:1px solid #d7e3df;border-radius:10px;padding:16px;display:grid;gap:8px;background:white}.stock-company strong{font-size:17px}.index-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}.index-tile{display:grid;gap:10px;background:white;padding:16px;border:1px solid #d7e3df;border-radius:10px}.index-tile small{color:#586e65}.index-directory{margin:20px 0;padding:18px;border:1px solid #d7e3df;border-radius:12px;background:#f8fbf9}.index-directory summary{cursor:pointer;font-weight:700}.index-region h3{margin:24px 0 14px}.index-intro h2{margin:12px 0}.stock-widget iframe{display:block!important;width:100%!important;height:var(--stock-frame-height)!important;min-height:0!important;border:0}.stock-widget .tradingview-widget-container__widget{height:var(--stock-frame-height)!important;min-height:0!important}.stock-widget-failed{min-height:0!important}.stock-widget:not(.chart){min-width:720px}.stock-widget[data-widget-type=technical-analysis]{min-width:0}.stock-card>div{overflow-x:auto;max-width:100%}.stock-grid{margin-top:16px}.stock-card .tradingview-widget-copyright{height:32px;line-height:28px;text-align:center}.stock-company small{color:#586e65}.stock-company button{justify-self:start}.stock-empty{padding:25px;background:#eef5f1}.stock-status{font-size:13px;color:#586e65;line-height:1.6}@media(max-width:650px){#stocksWorkspace{padding:15px}.stock-intro{display:block}.stock-widget.chart{height:500px}.asset-nav{padding:12px}.stock-controls>*{width:100%}}`;document.head.append(style);
const universe=[['NASDAQ:NVDA','NVIDIA','Chips'],['NASDAQ:AMD','AMD','Chips'],['NASDAQ:AVGO','Broadcom','Chips'],['NASDAQ:ARM','Arm','Chips'],['NASDAQ:QCOM','Qualcomm','Chips'],['NASDAQ:INTC','Intel','Chips'],['NASDAQ:MU','Micron','Memory & manufacturing'],['NYSE:TSM','TSMC (US ADR)','Memory & manufacturing'],['NASDAQ:ASML','ASML (US listing)','Equipment & design'],['NASDAQ:AMAT','Applied Materials','Equipment & design'],['NASDAQ:LRCX','Lam Research','Equipment & design'],['NASDAQ:KLAC','KLA','Equipment & design'],['NASDAQ:SNPS','Synopsys','Equipment & design'],['NASDAQ:CDNS','Cadence','Equipment & design'],['NASDAQ:MSFT','Microsoft','Cloud & software'],['NASDAQ:GOOGL','Alphabet','Cloud & software'],['NASDAQ:AMZN','Amazon','Cloud & software'],['NASDAQ:META','Meta','Cloud & software'],['NYSE:ORCL','Oracle','Cloud & software'],['NYSE:IBM','IBM','Cloud & software'],['NYSE:ANET','Arista Networks','Infrastructure'],['NYSE:DELL','Dell','Infrastructure'],['NYSE:HPE','HPE','Infrastructure'],['NYSE:VRT','Vertiv','Infrastructure'],['NYSE:ETN','Eaton','Infrastructure']];
const regions={Americas:[['SP:SPX','S&P 500'],['NASDAQ:NDX','Nasdaq 100'],['DJ:DJI','Dow Jones'],['TVC:RUT','Russell 2000'],['TSX:TSX','S&P/TSX'],['BMFBOVESPA:IBOV','Bovespa']],Europe:[['TVC:UKX','FTSE 100'],['XETR:DAX','DAX'],['EURONEXT:PX1','CAC 40'],['TVC:SX5E','Euro Stoxx 50'],['SIX:SMI','SMI'],['BME:IBC','IBEX 35']],Asia:[['NSE:NIFTY','Nifty 50'],['BSE:SENSEX','Sensex'],['NSE:BANKNIFTY','Nifty Bank'],['TVC:NI225','Nikkei 225'],['TSE:TOPIX','TOPIX'],['HSI:HSI','Hang Seng'],['SSE:000001','Shanghai Composite'],['SSE:000300','CSI 300'],['KRX:KOSPI','KOSPI'],['TWSE:TAIEX','Taiwan Weighted'],['ASX:XJO','ASX 200'],['TVC:STI','Straits Times']], 'Middle East & Africa':[['TADAWUL:TASI','Tadawul All Share'],['JSE:J200','South Africa Top 40']]};
let saved=[];try{const v=JSON.parse(localStorage.getItem('radar.stockWatch')||'[]');if(Array.isArray(v))saved=v.filter(s=>universe.some(x=>x[0]===s))}catch{}
const references={Americas:[['FOREXCOM:SPXUSD','S&P 500 · cash CFD'],['FOREXCOM:NSXUSD','US 100 · cash CFD'],['FOREXCOM:DJI','Dow 30 · cash CFD']],Europe:[['INDEX:DEU40','DAX'],['INDEX:CAC40','CAC 40'],['INDEX:SX5E','Euro Stoxx 50'],['INDEX:SMI','SMI'],['FOREXCOM:UKXGBP','UK 100 · cash CFD']],Asia:[['INDEX:NKY','Nikkei 225'],['INDEX:HSI','Hang Seng'],['BSE:SENSEX','Sensex'],['INDEX:KSIC','Kospi Composite']]};
let equityMarket='us',equityColumns='overview';let quoteMode='references';let selectedIndex='';let active='indices';let region='Americas';let symbol='NASDAQ:NVDA';
stocks.innerHTML='<div class="stock-intro"><div><small>EQUITIES · GLOBAL MARKETS</small><h1>Global markets</h1><p>Indices, stock screening and AI & computing — in separate, readable views.</p></div></div><div class="stock-note"><strong>Latest available provider data</strong> · Embedded stock quotes may be delayed or restricted by exchange licensing. Check the source timestamp and market session. Prices use each listing’s currency. No zero-delay guarantee.</div><nav class="stock-tabs" aria-label="Stocks sections"><button data-stock-tab="indices">Global indices</button><button data-stock-tab="screener">Stock screener</button><button data-stock-tab="ai">AI & Computing</button></nav><section id="stockContent"></section>';
const content=stocks.querySelector('#stockContent');const capabilities=document.createElement('p');capabilities.className='stock-note stock-capabilities';capabilities.textContent='Global markets: charts and provider screeners are available. Account positions, orders, strategy alerts and background scans require a global broker/data connection. Fyers serves Indian instruments; it does not connect foreign exchanges.';const dataDetails=document.createElement('details');dataDetails.className='market-data-details';const dataSummary=document.createElement('summary');dataSummary.textContent='Data availability & supported features';dataDetails.append(dataSummary,stocks.querySelector('.stock-note'),capabilities);stocks.insertBefore(dataDetails,content);
function marketLink(href,title){const a=document.createElement('a');a.href=href;a.target='_blank';a.rel='noopener noreferrer';a.className='market-button stock-open-provider';a.textContent=title;return a}
function openIndianChart(ticker){const map={'NSE:NIFTY':'NSE:NIFTY50-INDEX','NSE:BANKNIFTY':'NSE:NIFTYBANK-INDEX','BSE:SENSEX':'BSE:SENSEX-INDEX'},symbol=map[ticker]||(/^NSE:[A-Z0-9&._-]+$/.test(ticker)?ticker+'-EQ':null);if(!symbol)return;document.querySelector('[data-asset="india"]')?.click();document.querySelector('[data-india="trade"]')?.click();const input=document.getElementById('indiaSymbol');if(input){input.value=symbol;input.onchange?.()}}

function widget(host,type,config,title,href,reload){
 host.innerHTML='';const note=document.createElement('p');note.className='stock-status';note.setAttribute('role','status');note.textContent='Loading provider panel…';host.append(note);const actions=document.createElement('div');actions.className='stock-controls stock-provider-actions';actions.append(marketLink(href,title+' on TradingView ↗'));host.append(actions);
 const requested=Number(config.height),height=Number.isFinite(requested)&&requested>=200?requested:type==='advanced-chart'?620:type==='technical-analysis'?420:640;
 const box=document.createElement('div');box.className='tradingview-widget-container stock-widget'+(type==='advanced-chart'?' chart':'');box.style.height=(height+32)+'px';box.style.setProperty('--stock-frame-height',height+'px');box.dataset.widgetHeight=String(height);box.dataset.widgetType=type;
 const mount=document.createElement('div');mount.className='tradingview-widget-container__widget';mount.style.height=height+'px';box.append(mount);
 const credit=document.createElement('div');credit.className='tradingview-widget-copyright';const link=document.createElement('a');link.href=href;link.target='_blank';link.rel='noopener noreferrer';link.textContent=title+' by TradingView ↗';credit.append(link);box.append(credit);
 const script=document.createElement('script');script.src='https://s3.tradingview.com/external-embedding/embed-widget-'+type+'.js';script.async=true;script.textContent=JSON.stringify({...config,width:'100%',height,autosize:false,locale:'en',colorTheme:'light'});
 let deadline=null;const settled=()=>{if(deadline!==null&&typeof clearTimeout==='function')clearTimeout(deadline)};script.onload=()=>{settled();if(!host.contains(note))return;note.textContent='Panel script loaded. Data availability is shown inside the provider panel. If it is blank or restricted, use Open on TradingView above or hide this panel.'};
 script.onerror=()=>{settled();if(!host.contains(note))return;note.textContent='Provider could not load. Check your connection or open TradingView using the link below.';box.style.height='auto';box.style.setProperty('--stock-frame-height','0px');mount.style.height='0px';box.classList.add('stock-widget-failed')};box.append(script);host.append(box);
 const retry=document.createElement('button');retry.type='button';retry.textContent='Reload this panel';retry.onclick=reload||(()=>widget(host,type,config,title,href));host.append(retry);const hide=document.createElement('button');hide.type='button';hide.textContent='Hide unavailable panel';hide.onclick=()=>{const hidden=box.hidden=!box.hidden;hide.textContent=hidden?'Show provider panel':'Hide unavailable panel'};host.append(hide);if(typeof setTimeout==='function')deadline=setTimeout(()=>{if(host.contains(note))note.textContent='Provider is taking longer than expected. Open on TradingView above, or reload this panel.'},15000)
}
function card(title){const el=document.createElement('section');el.className='stock-card';const h=document.createElement('h2');h.textContent=title;el.append(h);const body=document.createElement('div');el.append(body);content.append(el);return body}
function renderIndexDirectory(){
 const intro=document.createElement('div');intro.className='index-intro';intro.innerHTML='<h2>Global indices</h2><p>26 benchmarks across the Americas, Europe, Asia, the Middle East and Africa. Choose an index to open its chart.</p>';content.append(intro);
 const directory=document.createElement('details');directory.className='index-directory';const summary=document.createElement('summary');summary.textContent='Browse all 26 cash benchmarks & full charts';directory.append(summary);
 for(const [area,rows] of Object.entries(regions)){
  const group=document.createElement('section');group.className='index-region';const title=document.createElement('h3');title.textContent=area;group.append(title);const grid=document.createElement('div');grid.className='index-grid';
  for(const [ticker,name] of rows){const item=document.createElement('article');item.className='index-tile';const label=document.createElement('strong');label.textContent=name;const code=document.createElement('small');code.textContent=ticker;const open=document.createElement('button');open.textContent='View chart';open.type='button';open.dataset.indexSymbol=ticker;open.onclick=event=>{selectedIndex=ticker;if(region!==area){region=area;render();if(event)document.getElementById('selectedIndexChart')?.scrollIntoView?.({behavior:'smooth',block:'start'});return}const selector=document.getElementById('indexSymbol');if(selector&&regions[region].some(x=>x[0]===ticker))selector.value=ticker;const target=document.getElementById('selectedIndexChart');target.innerHTML='';const h=document.createElement('h2');h.textContent=name;target.append(h);const body=document.createElement('div');target.append(body);chart(body,ticker);if(event)target.scrollIntoView?.({behavior:'smooth',block:'start'})};const link=document.createElement('a');link.href='https://www.tradingview.com/chart/?symbol='+encodeURIComponent(ticker);link.target='_blank';link.rel='noopener noreferrer';link.textContent='TradingView ↗';item.append(label,code,open,link);grid.append(item)}group.append(grid);directory.append(group)
 }
 content.append(directory);const selected=document.createElement('section');selected.className='stock-card';selected.id='selectedIndexChart';selected.innerHTML='<h2>Your selected index chart</h2><p>Choose View chart above. Prices and changes are supplied by the provider panel below; index cards do not display substituted prices.</p>';content.append(selected);
}
function quotes(host,rows,title){const embedded=rows.filter(r=>!r[0].startsWith('NSE:'));if(!embedded.length){host.innerHTML='';const note=document.createElement('p');note.className='stock-status';note.textContent='These NSE quotes require your FYERS connection or a full TradingView chart.';host.append(note)}else widget(host,'market-quotes',{height:Math.max(280,Math.min(980,100+rows.length*36)),symbolsGroups:[{name:title,symbols:embedded.map(x=>({name:x[0],displayName:x[1]}))}],showSymbolLogo:true,isTransparent:false},'Market quotes','https://www.tradingview.com/markets/',()=>quotes(host,rows,title));const links=document.createElement('p');links.className='stock-status';links.textContent='If a symbol is restricted in the embedded table, open its full chart: ';for(const row of rows){const a=document.createElement('a');a.href='https://www.tradingview.com/chart/?symbol='+encodeURIComponent(row[0]);a.target='_blank';a.rel='noopener noreferrer';a.textContent=row[1]+' · ';links.append(a)}host.append(links)}
let chartCleanup=null;function clearStockChart(){chartCleanup?.();chartCleanup=null}nav.addEventListener('click',e=>{if(e.target.closest('[data-asset]')?.dataset.asset==='india')clearStockChart()});
function chart(host,s){clearStockChart();if(typeof window!=='undefined'&&window.RadarTradingView){chartCleanup=window.RadarTradingView.mount(host,{symbol:s,tradingViewSymbol:true,allowSymbolChange:true});return}widget(host,'advanced-chart',{symbol:s,interval:'D',timezone:'Etc/UTC',theme:'light',style:'1',allow_symbol_change:true,save_image:true,hide_top_toolbar:false,hide_side_toolbar:false,withdateranges:true,details:true,calendar:false,support_host:'https://www.tradingview.com'},'Open full chart','https://www.tradingview.com/chart/?symbol='+encodeURIComponent(s))}
function render(){clearStockChart();content.innerHTML='';stocks.querySelectorAll('[data-stock-tab]').forEach(b=>{if(b.dataset.stockTab===active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(active==='indices'){renderIndexDirectory();const controls=document.createElement('div');controls.className='stock-controls';controls.innerHTML='<label>Region<select id="stockRegion"></select></label><label>Quote source<select id="indexQuoteMode"><option value="references">Public reference feed (CFDs marked)</option><option value="cash">Cash benchmarks (may be restricted)</option></select></label><label>Index chart<select id="indexSymbol"></select></label>';content.append(controls);const select=controls.querySelector('#stockRegion');Object.keys(regions).forEach(r=>{const o=document.createElement('option');o.value=r;o.textContent=r;select.append(o)});select.value=region;const idx=controls.querySelector('#indexSymbol');regions[region].forEach(r=>{const o=document.createElement('option');o.value=r[0];o.textContent=r[1];idx.append(o)});const mode=controls.querySelector('#indexQuoteMode');mode.value=quoteMode;mode.onchange=()=>{quoteMode=mode.value;render()};const ref=quoteMode==='references'&&references[region],quoteRows=ref||regions[region],q=card(region+(ref?' · public reference quotes':' · cash benchmarks'));quotes(q,quoteRows,region);const basis=document.createElement('p');basis.className='stock-note';basis.textContent=ref?'Source: TradingView public widget examples. Rows marked cash CFD are broker reference instruments; they can differ from the official cash index. This feed is for market context.':'Cash-index availability depends on the exchange licence. If the provider cannot show an index here, its full TradingView chart remains linked below.';q.prepend(basis);const directory=content.querySelector('.index-directory'),selected=content.querySelector('#selectedIndexChart');content.prepend(controls);content.insertBefore(q.parentElement,directory);content.insertBefore(selected,directory);if(!regions[region].some(x=>x[0]===selectedIndex))selectedIndex=regions[region][0][0];if(selectedIndex){idx.value=selectedIndex;[...content.querySelectorAll('[data-index-symbol]')].find(b=>b.dataset.indexSymbol===selectedIndex)?.onclick()}select.onchange=()=>{region=select.value;selectedIndex='';render()};idx.onchange=()=>{const choice=[...content.querySelectorAll('[data-index-symbol]')].find(b=>b.dataset.indexSymbol===idx.value);choice?.click()};}
if(active==='screener'){content.innerHTML='<h2>Find stocks in your market</h2><p>Use the provider’s filters for valuation, performance, volume and technicals. Results are research candidates, not confirmed trade setups.</p><div class="stock-controls"><label>Listing market<select id="equityMarket"><option value="us">United States</option><option value="india">India</option><option value="uk">United Kingdom</option><option value="canada">Canada</option><option value="germany">Germany</option><option value="france">France</option><option value="japan">Japan</option><option value="hongkong">Hong Kong</option><option value="china">China</option><option value="australia">Australia</option><option value="singapore">Singapore</option><option value="southkorea">South Korea</option><option value="taiwan">Taiwan</option><option value="brazil">Brazil</option></select></label><label>View<select id="equityColumns"><option value="overview">Overview</option><option value="performance">Performance</option><option value="technical">Technicals</option></select></label></div>';content.querySelector('#equityMarket').value=equityMarket;content.querySelector('#equityColumns').value=equityColumns;const panel=card('Stock screener');const load=()=>{equityMarket=content.querySelector('#equityMarket').value;equityColumns=content.querySelector('#equityColumns').value;widget(panel,'screener',{market:equityMarket,defaultColumn:equityColumns,defaultScreen:'most_capitalized',showToolbar:true},'Full stock screener','https://www.tradingview.com/screener/')};content.querySelectorAll('select').forEach(s=>s.onchange=load);load()}
if(active==='ai'){content.innerHTML='<h2>AI & Computing</h2><p>A curated 25-company research universe across chips, cloud and infrastructure. Overseas companies here use their US listings; this is not a complete global AI universe.</p><div class="stock-controls"><label>Search company<input id="aiSearch" type="search" placeholder="Name or ticker"></label><label>Supply chain<select id="aiTheme"><option value="">All themes</option></select></label><label>Tracking<select id="aiTracking"><option value="all">All companies</option><option value="saved">My watchlist</option></select></label></div><p id="aiCount" role="status"></p><div id="aiCompanies" class="stock-grid"></div><p class="stock-status" id="stockSaveStatus">Watchlist saved in this browser only. Stocks do not send crypto alerts or place exchange orders.</p>';const themes=content.querySelector('#aiTheme');[...new Set(universe.map(x=>x[2]))].forEach(t=>{const o=document.createElement('option');o.value=t;o.textContent=t;themes.append(o)});const q=card('Screened basket · latest available quotes');const c=card('Selected company chart');chart(c,symbol);const tech=card('Selected company · technical summary');const technical=()=>widget(tech,'technical-analysis',{symbol,interval:'1h',showIntervalTabs:true,displayMode:'single',isTransparent:false},'Technical analysis','https://www.tradingview.com/symbols/'+symbol.replace(':','-')+'/technicals/');technical();const draw=()=>{const search=content.querySelector('#aiSearch').value.trim().toLowerCase();const rows=universe.filter(x=>(!themes.value||x[2]===themes.value)&&(!search||x.join(' ').toLowerCase().includes(search))&&(content.querySelector('#aiTracking').value!=='saved'||saved.includes(x[0])));content.querySelector('#aiCount').textContent=rows.length+' companies · Select Chart to inspect price and technicals.';const list=content.querySelector('#aiCompanies');list.innerHTML='';for(const row of rows){const item=document.createElement('article');item.className='stock-company';const name=document.createElement('strong');name.textContent=row[1];const meta=document.createElement('small');meta.textContent=row[0]+' · '+row[2];const view=document.createElement('button');view.textContent='Chart ↗';view.onclick=()=>{symbol=row[0];chart(c,symbol);technical();c.parentElement.scrollIntoView?.({behavior:'smooth',block:'start'})};const save=document.createElement('button');save.textContent=saved.includes(row[0])?'★ Tracking':'☆ Track';save.setAttribute('aria-pressed',String(saved.includes(row[0])));save.onclick=()=>{saved=saved.includes(row[0])?saved.filter(s=>s!==row[0]):[...saved,row[0]];try{localStorage.setItem('radar.stockWatch',JSON.stringify(saved))}catch{content.querySelector('#stockSaveStatus').textContent='Browser storage unavailable. Changes last only until this page is closed.'}draw()};item.append(name,meta,view,save);list.append(item)}if(rows.length)quotes(q,rows,'AI & Computing');else{q.textContent='No companies match these filters.';list.textContent='No matches. Change the filters or track a company from All companies.'}};content.querySelector('#aiSearch').oninput=draw;content.querySelector('#aiSearch').onchange=draw;themes.onchange=draw;content.querySelector('#aiTracking').onchange=draw;draw()}}
stocks.querySelectorAll('[data-stock-tab]').forEach(b=>b.onclick=()=>{active=b.dataset.stockTab;render()});nav.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>{const on=['stocks','indices'].includes(b.dataset.asset);if(b.dataset.asset==='indices')active='indices';if(b.dataset.asset==='stocks')active='screener';crypto.hidden=on;stocks.hidden=!on;nav.querySelectorAll('[data-asset]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if(on)render();else {clearStockChart();content.innerHTML=''}});
})();
